create or replace function public.post_gateway_refund_financial_journal() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.status='approved' and (tg_op='INSERT' or old.status is distinct from 'approved') then perform public.post_gateway_financial_journal(new.user_id,new.transaction_id,new.gateway_id,'refund','refund:'||new.id::text,new.currency,jsonb_build_array(jsonb_build_object('account_code','merchant_refunds','direction','debit','amount',new.amount),jsonb_build_object('account_code','gateway_receivable','direction','credit','amount',new.amount)),jsonb_build_object('external_refund_id',new.external_refund_id,'source','gateway_refund')); end if; return new; end $$;
drop trigger if exists trg_gateway_refund_financial_posting on public.gateway_refunds;
create trigger trg_gateway_refund_financial_posting after insert or update of status on public.gateway_refunds for each row execute function public.post_gateway_refund_financial_journal();
